// ============================================================
// CONFIG — único bloco que deveria precisar de ajuste
// ============================================================
const CONFIG = {
  codigoTelevendas: "",   // código de vendedor tratado como grupo TELEVENDAS (deixe vazio se não houver)
  emailGestor: "gestor@exemplo.com",
  nomeGestor: "Nome do Gestor",
  assuntoEmailGestor: "Relatório Consolidado Semanal - Coach de Vendas NOME DA EMPRESA",
  ocultarGruposSemAtividade: true
};

function pegarRegistros(nodeJson) {
  if (!nodeJson) return [];
  if (!nodeJson.dados) return [];
  if (!Array.isArray(nodeJson.dados) || nodeJson.dados.length === 0) return [];
  const bloco = nodeJson.dados[0];
  if (!bloco || !Array.isArray(bloco.dados)) return [];
  return bloco.dados;
}

function chaveGrupo(brutoCodigo) {
  let texto = (brutoCodigo === null || brutoCodigo === undefined) ? "" : String(brutoCodigo).trim();
  if (texto === "") return "TELEVENDAS";
  if (texto.toUpperCase() === "TELEVENDAS") return "TELEVENDAS";
  if (/^-?\d+(\.\d+)?$/.test(texto)) {
    const numero = Number(texto);
    if (!isNaN(numero)) texto = String(numero);
  }
  if (texto === String(CONFIG.codigoTelevendas)) return "TELEVENDAS";
  return texto;
}

function formatarMoeda(valor) {
  const numero = Number(valor) || 0;
  const negativo = numero < 0;
  const fixo = Math.abs(numero).toFixed(2);
  const partes = fixo.split(".");
  let inteiro = partes[0];
  const centavos = partes[1];
  let comSeparador = "";
  let contador = 0;
  for (let i = inteiro.length - 1; i >= 0; i--) {
    comSeparador = inteiro.charAt(i) + comSeparador;
    contador++;
    if (contador % 3 === 0 && i !== 0) {
      comSeparador = "." + comSeparador;
    }
  }
  return (negativo ? "-R$ " : "R$ ") + comSeparador + "," + centavos;
}

function parseMoedaPlanilha(valor) {
  if (typeof valor === "number") return valor;
  if (!valor) return 0;
  const texto = String(valor).trim();
  if (texto === "") return 0;
  const semMilhar = texto.replace(/\./g, "").replace(",", ".");
  const numero = parseFloat(semMilhar);
  return isNaN(numero) ? 0 : numero;
}

// Os nomes vindos do ERP (Clientes/Vendedores) as vezes chegam ja com entidades HTML
// (ex.: "BEBIDAS &amp; ALIMENTOS"), provavelmente de uma exportacao antiga. Decodifica
// de volta para texto puro antes de usar em qualquer lugar (WhatsApp nao entende HTML).
function decodificarEntidadesHtml(texto) {
  if (texto === null || texto === undefined) return "";
  return String(texto)
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, "\"")
    .replace(/&#39;/g, "'")
    .replace(/&apos;/g, "'");
}

function formatarDataBr(dataIso) {
  if (!dataIso) return "-";
  const partes = String(dataIso).split("T")[0].split("-");
  if (partes.length !== 3) return "-";
  return partes[2] + "/" + partes[1] + "/" + partes[0];
}

function ehDataNula(dataIso) {
  if (!dataIso) return true;
  return String(dataIso).indexOf("1900-01-01") === 0;
}

function diasEntre(dataIsoAntiga, agoraIso) {
  const inicio = new Date(dataIsoAntiga);
  const fim = new Date(agoraIso);
  const diffMs = fim.getTime() - inicio.getTime();
  return Math.floor(diffMs / (1000 * 60 * 60 * 24));
}

// --- WhatsApp / Z-API: extração e normalização de telefone ---
// Suposição: não sabemos o nome exato do campo de telefone no relatório
// de Data Lab "Vendedores". Testamos as variações mais prováveis, nessa
// ordem de prioridade. Ajuste esta lista se o campo real tiver outro nome.
function pegarTelefoneBruto(v) {
  const candidatos = [v.telefone, v.celular, v.fone, v.whatsapp, v.phone];
  for (let i = 0; i < candidatos.length; i++) {
    const c = candidatos[i];
    if (c !== null && c !== undefined && String(c).trim() !== "") return String(c).trim();
  }
  return "";
}

// Remove tudo que não for dígito e prefixa "55" (DDI Brasil) quando o
// número já tiver DDD + número (10 ou 11 dígitos) e ainda não começar com 55.
function normalizarTelefoneWhatsapp(bruto) {
  if (!bruto) return "";
  const digitos = String(bruto).replace(/\D/g, "");
  if (digitos === "") return "";
  if (digitos.indexOf("55") === 0) return digitos;
  if (digitos.length === 10 || digitos.length === 11) return "55" + digitos;
  return digitos;
}

// Telefone válido para WhatsApp: 55 + DDD (dois dígitos de 1 a 9) + 8 dígitos (fixo)
// ou 9 dígitos começando com 9 (celular). Inválido não vai para o WhatsApp e entra na lista do gestor.
function telefoneWhatsappValido(normalizado) {
  if (!/^55[1-9][1-9]\d{8,9}$/.test(normalizado)) return false;
  return normalizado.length === 12 || normalizado.charAt(4) === "9";
}

function emailValido(email) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

// --- Comissão: detecta e interpreta a coluna de comissão da planilha ---
// Heurística adotada (documentada no relatório de entrega, confirme com o usuário):
//   - Tem "%" no texto            -> percentual (ex.: "5%" = 5%)
//   - Número entre 0 e 1 (excl.)  -> percentual em fração (ex.: 0.05 = 5%)
//   - Número entre 1 e 100        -> percentual (ex.: "5" = 5%, "12.5" = 12.5%)
//   - Número maior que 100        -> valor fixo em reais (ex.: "350" = R$ 350,00 fixos)
function parseComissaoPlanilha(valorBruto) {
  if (valorBruto === null || valorBruto === undefined) return { percentual: null, valorFixo: null };
  const texto = String(valorBruto).trim();
  if (texto === "") return { percentual: null, valorFixo: null };
  const temSimboloPercentual = texto.indexOf("%") !== -1;
  const textoLimpo = texto.replace("%", "").trim();
  const numero = parseMoedaPlanilha(textoLimpo);
  if (temSimboloPercentual) {
    return { percentual: numero, valorFixo: null };
  }
  if (numero > 0 && numero < 1) {
    return { percentual: numero * 100, valorFixo: null };
  }
  if (numero >= 1 && numero <= 100) {
    return { percentual: numero, valorFixo: null };
  }
  if (numero > 100) {
    return { percentual: null, valorFixo: numero };
  }
  return { percentual: null, valorFixo: null };
}

const vendas = pegarRegistros($node["Vendas do mes"].json);
const clientes = pegarRegistros($node["Clientes"].json);
const vendedoresCad = pegarRegistros($node["Vendedores"].json);

function normalizarTexto(txt) {
  return String(txt || "")
    .trim()
    .toLowerCase()
    .replace(/[áàãâä]/g, "a")
    .replace(/[éêè]/g, "e")
    .replace(/[íîì]/g, "i")
    .replace(/[óôõò]/g, "o")
    .replace(/[úûù]/g, "u")
    .replace(/ç/g, "c");
}

// "Metas por Vendedor" usa a operação "get_rows" do Google Sheets: cada item de
// entrada já é UMA LINHA, com um campo por coluna do cabeçalho (ex.: item.json.codigo,
// item.json.meta) — sem precisar ler matriz A1 crua nem descobrir índice de coluna.
// Ainda assim comparamos os nomes das colunas de forma tolerante a acento/maiúscula,
// caso o cabeçalho real da planilha esteja escrito diferente destes candidatos.
function pegarCampoLinha(linha, candidatos) {
  const chaves = Object.keys(linha);
  const normalizadas = chaves.map(normalizarTexto);
  for (let i = 0; i < candidatos.length; i++) {
    const idx = normalizadas.findIndex(function (k) { return k.indexOf(candidatos[i]) !== -1; });
    if (idx !== -1) return linha[chaves[idx]];
  }
  return undefined;
}

// Só processamos/enviamos para vendedores que TÊM uma linha na planilha de metas
// (pedido do usuário: "descartar" quem não está na planilha, avisando o gestor à
// parte). Guardamos os códigos aqui, à parte de metaPorGrupo, porque uma linha
// pode existir na planilha com meta em branco/zerada — mesmo assim ela conta como
// "está na planilha" (não é a mesma coisa que "tem meta > 0").
const metaPorGrupo = {};
const emailPorGrupoPlanilha = {};
const comissaoPorGrupo = {};
const codigosNaPlanilha = {};
for (let i = 0; i < items.length; i++) {
  const linha = items[i].json || {};
  const codigoBruto = pegarCampoLinha(linha, ["codigo", "vendedor"]);
  const grupo = chaveGrupo(codigoBruto);

  if (codigoBruto !== undefined && codigoBruto !== null && String(codigoBruto).trim() !== "") {
    codigosNaPlanilha[grupo] = true;
  }

  const meta = parseMoedaPlanilha(pegarCampoLinha(linha, ["meta"]));
  if (meta > 0) {
    metaPorGrupo[grupo] = meta;
  }

  const emailPlanilha = String(pegarCampoLinha(linha, ["email", "e-mail"]) || "").trim();
  if (emailPlanilha !== "") {
    emailPorGrupoPlanilha[grupo] = emailPlanilha;
  }

  // Detecção da coluna de comissão (bug reportado originalmente: "problema pra
  // acessar a comissão na tabela" — essa coluna nunca era lida pelo código anterior).
  const comissaoBruta = pegarCampoLinha(linha, ["comissao"]);
  if (comissaoBruta !== undefined) {
    const infoComissao = parseComissaoPlanilha(comissaoBruta);
    if (infoComissao.percentual !== null || infoComissao.valorFixo !== null) {
      comissaoPorGrupo[grupo] = infoComissao;
    }
  }
}

const nomePorGrupo = {};
const emailPorGrupo = {};
const telefonePorGrupo = {};
const telefoneBrutoPorGrupo = {};
for (let i = 0; i < vendedoresCad.length; i++) {
  const v = vendedoresCad[i];
  const grupo = chaveGrupo(v.codigo);
  nomePorGrupo[grupo] = decodificarEntidadesHtml(v.nome) || ("Vendedor " + grupo);
  emailPorGrupo[grupo] = (v.email || "").trim();
  telefoneBrutoPorGrupo[grupo] = pegarTelefoneBruto(v);
  telefonePorGrupo[grupo] = normalizarTelefoneWhatsapp(telefoneBrutoPorGrupo[grupo]);
}

const vendasPorGrupo = {};
for (let i = 0; i < vendas.length; i++) {
  const v = vendas[i];
  const cancelada = !ehDataNula(v.datacancela);
  if (cancelada) continue;
  const grupo = chaveGrupo(v.vendedor);
  if (!vendasPorGrupo[grupo]) vendasPorGrupo[grupo] = [];
  vendasPorGrupo[grupo].push(v);
}

const clientesPorGrupo = {};
for (let i = 0; i < clientes.length; i++) {
  const c = clientes[i];
  const grupo = chaveGrupo(c.vendedor_codigo);
  if (!clientesPorGrupo[grupo]) clientesPorGrupo[grupo] = [];
  clientesPorGrupo[grupo].push(c);
}

const todosGrupos = {};
Object.keys(clientesPorGrupo).forEach(function (g) { todosGrupos[g] = true; });
Object.keys(vendasPorGrupo).forEach(function (g) { todosGrupos[g] = true; });
Object.keys(metaPorGrupo).forEach(function (g) { todosGrupos[g] = true; });
Object.keys(nomePorGrupo).forEach(function (g) { todosGrupos[g] = true; });

// Vendedores com atividade real no mês (venda ou cliente na carteira) mas SEM
// linha na planilha de metas: ficam de fora do envio por completo — nem
// WhatsApp, nem e-mail — e viram só uma nota informativa no relatório do
// gestor. Restrito a quem TEVE atividade (não a todo cadastro) e exclui o
// grupo sintético "TELEVENDAS" (não é um vendedor de verdade, não faz sentido
// cobrar meta dele).
const gruposComAtividade = {};
Object.keys(clientesPorGrupo).forEach(function (g) { gruposComAtividade[g] = true; });
Object.keys(vendasPorGrupo).forEach(function (g) { gruposComAtividade[g] = true; });

const nomesForaDaPlanilha = [];
Object.keys(gruposComAtividade).forEach(function (g) {
  if (g !== "TELEVENDAS" && !codigosNaPlanilha[g]) {
    nomesForaDaPlanilha.push(nomePorGrupo[g] || ("Vendedor " + g));
  }
});

const agora = $now;
const vendedoresSemEmail = [];
const vendedoresSemTelefone = [];
const linhasResumoGestor = [];
const vendedoresParaEnviar = [];
let faturamentoTotalEmpresa = 0;
let metaTotalEmpresa = 0;
let comissaoTotalEmpresa = 0;
let gruposSemAtividadeOcultos = 0;

const gruposOrdenados = Object.keys(todosGrupos).filter(function (g) { return !!codigosNaPlanilha[g]; });

for (let g = 0; g < gruposOrdenados.length; g++) {
  const grupo = gruposOrdenados[g];
  const vendasDoGrupo = vendasPorGrupo[grupo] || [];
  const clientesDoGrupo = clientesPorGrupo[grupo] || [];
  const nome = nomePorGrupo[grupo] || ("Vendedor " + grupo);
  const emailInformado = emailPorGrupoPlanilha[grupo] || emailPorGrupo[grupo] || "";
  const email = emailValido(emailInformado) ? emailInformado : "";
  const telefoneBruto = telefoneBrutoPorGrupo[grupo] || "";
  const telefone = telefoneWhatsappValido(telefonePorGrupo[grupo] || "") ? telefonePorGrupo[grupo] : "";

  let faturamentoAtual = 0;
  const clientesAtendidosCodigos = {};
  for (let i = 0; i < vendasDoGrupo.length; i++) {
    faturamentoAtual += Number(vendasDoGrupo[i].total) || 0;
    clientesAtendidosCodigos[vendasDoGrupo[i].cliente] = true;
  }

  const qtdAtendidos = Object.keys(clientesAtendidosCodigos).length;

  const clientesPendentes = [];
  for (let i = 0; i < clientesDoGrupo.length; i++) {
    const c = clientesDoGrupo[i];
    if (!clientesAtendidosCodigos[c.codigo]) clientesPendentes.push(c);
  }

  const temAtividade = (faturamentoAtual > 0) || (qtdAtendidos > 0) || (clientesPendentes.length > 0);
  if (!temAtividade && CONFIG.ocultarGruposSemAtividade) {
    gruposSemAtividadeOcultos++;
    continue;
  }

  const meta = metaPorGrupo[grupo] || 0;
  const percentual = meta > 0 ? (faturamentoAtual / meta * 100) : null;

  faturamentoTotalEmpresa += faturamentoAtual;
  metaTotalEmpresa += meta;

  // Cálculo da comissão do vendedor
  const comissaoInfo = comissaoPorGrupo[grupo];
  let percentualComissao = null;
  let valorComissao = 0;
  const temComissaoCadastrada = !!comissaoInfo;
  if (comissaoInfo) {
    if (comissaoInfo.percentual !== null) {
      percentualComissao = comissaoInfo.percentual;
      valorComissao = faturamentoAtual * (percentualComissao / 100);
    } else if (comissaoInfo.valorFixo !== null) {
      valorComissao = comissaoInfo.valorFixo;
    }
  }
  comissaoTotalEmpresa += valorComissao;

  // Lista COMPLETA de clientes pendentes (sem corte) — quem monta a versão resumida
  // pro WhatsApp e a versão completa pro PDF/e-mail é o node "Montar Mensagens do
  // Vendedor", que roda depois, dentro do loop. Aqui só entregamos o dado bruto.
  const clientesPendentesDetalhados = clientesPendentes.map(function (c) {
    const nulo = ehDataNula(c.dtultimacompra);
    const dias = nulo ? 999999 : diasEntre(c.dtultimacompra, agora);

    return {
      codigo: c.codigo,
      nome: decodificarEntidadesHtml(c.nome),
      dataUltimaCompra: nulo ? "Nunca comprou" : formatarDataBr(c.dtultimacompra),
      diasSemComprar: nulo ? "-" : String(dias),
      diasOrdenacao: dias
    };
  });

  clientesPendentesDetalhados.sort(function (a, b) { return b.diasOrdenacao - a.diasOrdenacao; });

  vendedoresParaEnviar.push({
    codigo: grupo,
    nome: nome,
    email: email,
    telefone: telefone,
    faturamento_atual: faturamentoAtual,
    meta: meta,
    percentual_atingimento: percentual,
    qtd_atendidos: qtdAtendidos,
    qtd_pendentes: clientesPendentes.length,
    comissao_percentual: percentualComissao,
    comissao_valor: valorComissao,
    comissao_cadastrada: temComissaoCadastrada,
    clientes_pendentes: clientesPendentesDetalhados
  });

  if (!email) {
    vendedoresSemEmail.push({ nome: nome, codigo: grupo,
      motivo: emailInformado ? "e-mail inválido: " + emailInformado : "sem e-mail cadastrado" });
  }
  if (!telefone) {
    vendedoresSemTelefone.push({ nome: nome, codigo: grupo,
      motivo: telefoneBruto ? "número inválido: " + telefoneBruto : "sem telefone cadastrado" });
  }

  linhasResumoGestor.push({
    grupo: grupo,
    nome: nome,
    faturamentoAtual: faturamentoAtual,
    meta: meta,
    percentual: percentual,
    qtdAtendidos: qtdAtendidos,
    qtdPendentes: clientesPendentes.length,
    comissaoValor: valorComissao,
    comissaoPercentual: percentualComissao,
    comissaoCadastrada: temComissaoCadastrada
  });
}

linhasResumoGestor.sort(function (a, b) {
  const pa = a.percentual === null ? -1 : a.percentual;
  const pb = b.percentual === null ? -1 : b.percentual;
  return pa - pb;
});

const percentualGlobal = metaTotalEmpresa > 0 ? (faturamentoTotalEmpresa / metaTotalEmpresa * 100) : null;

// Só dados aqui — nenhum HTML é montado neste node. O HTML do e-mail do
// gestor é responsabilidade do node "Montar E-mail do Gestor", alimentado
// pela saída "concluído" do loop (ver esse node para o porquê).
return [{
  json: {
    gerado_em: agora,
    vendedores: vendedoresParaEnviar,
    relatorio_gestor: {
      email_gestor: CONFIG.emailGestor,
      assunto: CONFIG.assuntoEmailGestor,
      nome_gestor: CONFIG.nomeGestor,
      faturamento_total_empresa: faturamentoTotalEmpresa,
      meta_total_empresa: metaTotalEmpresa,
      percentual_atingimento_global: percentualGlobal,
      comissao_total_empresa: comissaoTotalEmpresa,
      vendedores_sem_email: vendedoresSemEmail,
      vendedores_sem_telefone: vendedoresSemTelefone,
      grupos_sem_atividade_ocultos: gruposSemAtividadeOcultos,
      vendedores_fora_da_planilha: nomesForaDaPlanilha,
      qtd_vendedores_fora_da_planilha: nomesForaDaPlanilha.length,
      linhas_resumo: linhasResumoGestor
    }
  }
}];

function formatarMoeda(valor) {
  const numero = Number(valor) || 0;
  const negativo = numero < 0;
  const fixo = Math.abs(numero).toFixed(2);
  const partes = fixo.split(".");
  let inteiro = partes[0];
  const centavos = partes[1];
  let comSeparador = "";
  let contador = 0;
  for (let i = inteiro.length - 1; i >= 0; i--) {
    comSeparador = inteiro.charAt(i) + comSeparador;
    contador++;
    if (contador % 3 === 0 && i !== 0) {
      comSeparador = "." + comSeparador;
    }
  }
  return (negativo ? "-R$ " : "R$ ") + comSeparador + "," + centavos;
}

function formatarMoedaAbreviada(valor) {
  const numero = Number(valor) || 0;
  const abs = Math.abs(numero);
  if (abs >= 1000000) {
    return (numero < 0 ? "-" : "") + "R$ " + (abs / 1000000).toFixed(1).replace(".", ",") + " mi";
  }
  if (abs >= 1000) {
    return (numero < 0 ? "-" : "") + "R$ " + Math.round(abs / 1000) + " mil";
  }
  return formatarMoeda(numero);
}

function formatarPercentual(valor) {
  if (valor === null || valor === undefined) return null;
  return valor.toFixed(1).replace(".", ",");
}

function escaparHtml(texto) {
  if (texto === null || texto === undefined) return "";
  return String(texto)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

// Faixas de cor do badge de % atingido, no mesmo espírito do design de referência
// (relatorio-meta-email-v2.html): cinza apagado (0%), cinza (abaixo de 70%),
// lilás claro (70%-99%), lilás forte (100%+ / meta batida).
function corBadgePercentual(pct) {
  if (pct === null || pct <= 0) return { bg: "#252942", cor: "#8b90a8" };
  if (pct < 70) return { bg: "#252942", cor: "#9a9fb5" };
  if (pct < 100) return { bg: "#2b2741", cor: "#b5abfc" };
  return { bg: "#423a6a", cor: "#d2cefd" };
}

function semanaEMesLabel(dataIso) {
  const d = dataIso ? new Date(dataIso) : new Date();
  const dCopy = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));
  const diaSemana = dCopy.getUTCDay() || 7;
  dCopy.setUTCDate(dCopy.getUTCDate() + 4 - diaSemana);
  const inicioAno = new Date(Date.UTC(dCopy.getUTCFullYear(), 0, 1));
  const semana = Math.ceil((((dCopy - inicioAno) / 86400000) + 1) / 7);
  const MESES = ["Jan", "Fev", "Mar", "Abr", "Mai", "Jun", "Jul", "Ago", "Set", "Out", "Nov", "Dez"];
  return "Semana " + semana + " &middot; " + MESES[d.getUTCMonth()] + "/" + d.getUTCFullYear();
}

// Roda uma única vez, alimentado pela saída "concluído" do loop "Cada Vendedor" —
// só monta o HTML final e passa pro node de envio. Toda a inteligência de dados
// (agrupar, calcular comissão, etc.) já foi feita antes, em "Processar Carteiras".
// Layout inspirado no modelo de referência relatorio-meta-email-v2.html.
const r = $node["Processar Carteiras"].json.relatorio_gestor;
const geradoEm = $node["Processar Carteiras"].json.gerado_em;
const linhas = r.linhas_resumo || [];

// -------- Pódio (top 3 por faturamento) --------
const porFaturamentoDesc = linhas.slice().sort(function (a, b) { return b.faturamentoAtual - a.faturamentoAtual; });
const podio = porFaturamentoDesc.slice(0, 3);
const RANK_LABEL = ["1º", "2º", "3º"];

let podioHtml = "";
for (let i = 0; i < podio.length; i++) {
  const p = podio[i];
  const destaque = i === 0;
  const borda = destaque ? "#5d5294" : "#333853";
  const badgeBg = destaque ? "#423a6a" : "#252942";
  const badgeCor = destaque ? "#d2cefd" : "#9a9fb5";
  const percLabel = p.percentual === null ? "sem meta" : formatarPercentual(p.percentual) + "% da meta";
  podioHtml +=
    '<td class="kpi" width="33.33%" valign="top" style="width:33.33%;padding:0 5px;">' +
    '<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="width:100%;background-color:#1e2133;border:1px solid ' + borda + ';border-radius:10px;"><tr><td style="padding:14px 14px 15px 14px;">' +
